package app.jarvis.ui.settings;

import java.util.Locale;

/** Short, actionable Russian explanations for standard settings section headers. */
final class SectionHelp {
    private SectionHelp() { }
    static String describe(String heading) {
        if (heading == null) return "Настройки выбранного раздела.";
        String normalized = heading.toUpperCase(Locale.ROOT).trim();
        if (normalized.startsWith("ИНСТРУМЕНТЫ ("))
            return "Инструменты сервера, доступные модели. Отключайте то, что агенту не требуется.";
        switch (normalized) {
            case "О ПРИЛОЖЕНИИ": return "Версия, платформа и сведения об устройстве. Эти данные помогают диагностировать проблемы совместимости.";
            case "ЖУРНАЛ": return "Количество сохраняемых записей и подробность событий. Большие журналы занимают больше места.";
            case "ОБСЛУЖИВАНИЕ": return "Сброс настроек и очистка истории — отдельные операции. Прочитайте подтверждение перед удалением.";
            case "ОТЧЁТЫ О СБОЯХ": return "Информация о предыдущих сбоях, пригодная для поиска причины ошибки. Здесь не выполняется автоматическая отправка.";
            case "ТЕМА": return "Выберите тёмное, светлое или системное оформление. Изменение применяется к экранам приложения.";
            case "АНИМАЦИЯ": return "Полная — плавные переходы. Сниженная — короткие затухания. Выкл — без анимации.";
            case "СТЕКЛО": return "Регулирует размытие и преломление прозрачных поверхностей. Режим «Авто» снижает качество при высокой нагрузке.";
            case "ОБРАЩЕНИЕ": return "Имя или обращение, которое ассистент может использовать в ответах. Поле можно оставить пустым.";
            case "РАЗРЕШЕНИЯ": return "Системные разрешения, нужные для фоновой работы. Предоставляйте только те, которые действительно используете.";
            case "АВТОЗАПУСК НА REALME / COLOROS / OPPO / VIVO": return "Настройки производителя могут запрещать фоновый запуск. Проверьте разрешение автозапуска и экономию батареи.";
            case "ПОСЛЕ ПЕРЕЗАГРУЗКИ ТЕЛЕФОНА": return "Управляет поведением службы после перезапуска Android. Реальный автозапуск зависит от разрешений системы.";
            case "СЛЕДУЮЩИЙ ЗАПРОС К МОДЕЛИ": return "Посмотрите, какие данные и инструкции попадут в следующий запрос к языковой модели.";
            case "СВОЙ ПРОМПТ": return "Дополнительные инструкции к поведению ассистента. Они не должны содержать пароли и токены.";
            case "ЧТО ВХОДИТ В ЗАПРОС": return "Состав системного сообщения, контекста диалога и информации об инструментах.";
            case "ПРОВЕРКИ": return "Запускает диагностику отдельных компонентов. Некоторые проверки требуют доступа к сети или разрешений.";
            case "ОТЧЁТ": return "Результаты последних диагностических проверок. Ошибки стоит сверять с журналом.";
            case "ПРОВАЙДЕР": return "Сервис, через который отправляются запросы модели. Для некоторых сервисов нужен личный API-ключ.";
            case "МОДЕЛЬ": return "Модель определяет стоимость, скорость и доступные функции. Список зависит от выбранного провайдера.";
            case "НЕДАВНИЕ": return "Недавно использованные модели для быстрого переключения.";
            case "ГЕНЕРАЦИЯ": return "Параметры ответа, такие как температура, лимит токенов, контекст и шаги агента.";
            case "ЗАПАСНЫЕ ПРОВАЙДЕРЫ": return "Порядок переключения при недоступности основной модели. Не все ошибки допускают автоматическую замену.";
            case "МОСТ": return "Локальное соединение между агентом и инструментами. Следите, чтобы доступ не был открыт посторонним.";
            case "ТОКЕН": return "Секрет для соединения с мостом. Не отправляйте его в чат и не публикуйте.";
            case "БЕЗОПАСНОСТЬ": return "Ограничения доступа к мосту и действиям агента. Меняйте их осознанно.";
            case "ГОТОВЫЕ ПОДКЛЮЧЕНИЯ": return "Преднастроенные серверы MCP. Для включения некоторых нужны отдельные программы или учётные данные.";
            case "СЕРВЕРЫ": return "Список подключённых MCP-серверов. Агент видит только доступные инструменты включённых серверов.";
            case "ПОВЕДЕНИЕ": return "Правила подключения и запуска сервера. Ошибки подключения проверяйте в диагностике.";
            case "ПОКАЗ ИНСТРУМЕНТОВ АГЕНТУ": return "Какие инструменты MCP будут доступны модели. Лишние инструменты увеличивают контекст.";
            case "ДЕЙСТВИЯ": return "Управление выбранным подключением. Некоторые действия влияют на работу инструментов.";
            case "НАЗВАНИЕ": return "Понятное локальное имя сервера или подключения.";
            case "АДРЕС": return "URL или путь сервера MCP. Укажите адрес только доверенного источника.";
            case "ТРАНСПОРТ": return "Способ обмена данными с сервером: локальный процесс или сетевое соединение.";
            case "ЗАГОЛОВОК АВТОРИЗАЦИИ": return "Данные авторизации для сервера. Храните ключи как секреты, не в открытых текстах.";
            case "ЛЮБИМАЯ ПЕСНЯ": return "Выбранная композиция для музыкальных команд и утреннего сценария.";
            case "УТРО": return "Настройка приветствия и запуска любимой песни по утренней фразе.";
            case "ПЕСОЧНИЦА": return "Изолированная папка для рабочих файлов ассистента. Следите за доступным местом.";
            case "ЧТО УМЕЕТ АГЕНТ": return "Список разрешённых возможностей и инструментов. Это не означает, что каждый внешний сервис доступен.";
            case "МОСТ В TERMUX": return "Связь с Termux для внешних команд. Проверьте разрешения Termux перед использованием.";
            case "ИНСТРУМЕНТЫ АГЕНТА": return "Команды, которые агент может вызвать. Некоторые требуют ADB, сети или Termux.";
            case "ПАМЯТЬ АССИСТЕНТА": return "Заметки, сохранённые для будущих диалогов. Их можно добавить или удалить вручную.";
            case "СЕРВЕР": return "Состояние Telegram-помощника и соединения с MCP. Доступ к аккаунтам требует отдельного входа.";
            case "АККАУНТЫ": return "Подключённые учётные записи Telegram. Импорт сессии может предоставить доступ к сообщениям.";
            case "ПРАВА АГЕНТА": return "Права чтения, отправки и управления Telegram. Выбирайте минимально необходимые.";
            case "ПОДТВЕРЖДЕНИЕ": return "Определяет, будет ли агент спрашивать разрешение перед действиями в Telegram.";
            case "ТОКЕН ПОМОЩНИКА": return "Локальный секрет соединения с Telegram-помощником. Не публикуйте его.";
            case "API_ID": return "Идентификатор приложения Telegram API. Его получают в настройках разработчика Telegram.";
            case "API_HASH": return "Секрет приложения Telegram API. Не раскрывайте его посторонним.";
            case "ТЕЛЕФОН": return "Номер для входа в Telegram. Требуется подтверждение кодом.";
            case "ИМЯ АККАУНТА": return "Локальная подпись учётной записи, видимая в приложении.";
            case "КОД": return "Одноразовый код входа, отправленный Telegram. Не передавайте его третьим лицам.";
            case "ПАРОЛЬ": return "Дополнительный пароль двухэтапной проверки Telegram, если включён.";
            case "СТРОКА СЕССИИ": return "Секрет доступа к Telegram-аккаунту. Импортируйте только свои сессии.";
            case "ТРИГГЕРЫ": return "Фразы для быстрых действий, часть которых выполняется без обращения к языковой модели.";
            case "СОСТОЯНИЕ": return "Текущее состояние соединения и последние ошибки.";
            case "ПОДКЛЮЧЕНИЕ": return "Параметры ADB по Wi-Fi: сопряжение и подключение используют разные порты.";
            case "КАК ПОДГОТОВИТЬ ТЕЛЕФОН": return "Включите параметры разработчика и беспроводную отладку. Используйте адрес и порт, показанные Android.";
            case "ЧТО ЭТО ТАКОЕ": return "Описание возможностей и ограничений этого раздела.";
            case "ОЗВУЧКА ОТВЕТОВ": return "Когда ассистент произносит ответы вслух. Настройка не влияет на текстовые сообщения.";
            case "ПРОВАЙДЕРЫ ОЗВУЧКИ": return "Порядок TTS-сервисов и их доступность. Приоритет определяется положением в цепочке.";
            case "КЛЮЧИ API": return "Секретные ключи провайдеров озвучки. Не публикуйте их и не передавайте третьим лицам.";
            case "СКОРОСТЬ РЕЧИ": return "Темп синтезированной речи. Доступные скорости зависят от провайдера.";
            case "РЕЖИМ ОБРАЩЕНИЯ": return "Способ активации голосового ассистента. На расход батареи влияет постоянное прослушивание.";
            case "РАСПОЗНАВАНИЕ РЕЧИ": return "Преобразование речи в текст, локально либо через выбранный сервис.";
            case "ЯЗЫК": return "Язык распознавания речи; выбор влияет на точность команд.";
            case "КАК ЭТО РАБОТАЕТ": return "Краткое описание порядка работы функции и её ограничений.";
            default: return "Раздел «" + heading + "». Здесь можно просмотреть связанные параметры и изменить их значения.";
        }
    }
}
